mapper.select:
select * from (
    -- 将id做处理，避免mybatis使用resultMap进行一对多查询时,自动去除相同id,处理方式:(CONCAT_WS('_', a.id, b.id))
    select
        IF('1' = #{params.removeRepeat}, a.id, CONCAT_WS('_', a.id, b.id)) as id,
        a.id as row_id,
        a.tenant_id, a.factory_code, a.dept_code, a.line_code, a.check_date, a.week,
        a.check_scope, a.check_type, a.check_user, a.check_user_dept, a.check_user_post,
        a.check_owner_dept, a.check_owner_post, a.check_owner_class_group, a.check_owner,
        a.check_owner_admin, a.problem_img, a.problem_desc, a.problem_type, a.problem_subclass,
        a.ext_json, a.fives_check, a.optimize_img, a.optimize_desc, a.check_user_post_region,
        a.owner_post_region, a.create_by, a.create_time, a.update_by, a.update_time,
        b.id as action_id, b.practical_finish_date, b.plan_finish_date, b.finish_state, b.verify_user_name,
        b.execute_user_name, b.status as action_status, b.action_title
    from mes3_manage_check_list a
    left join mes3_action_plan_track b on a.id = b.data_id and b.problem_type_id = #{actionProblemTypeId} and b.del_flag = 0
    where a.del_flag = 0

        and a.problem_type like concat(#{params.problemType}, '%')


        and a.problem_type in

            #{item}



        and a.problem_subclass = #{params.problemSubclass}


        and a.check_user in (${params.checkUser})


        and a.check_owner in (${params.checkOwner})


        and a.check_user_dept in (${params.checkUserDept})


        and a.check_owner_dept in (${params.checkOwnerDept})


        and a.check_type = #{params.checkType}


        and a.check_date >= #{params.checkDate_begin}
        and a.check_date <= #{params.checkDate_end}


        and a.create_time >= #{params.createTime_begin}
        and a.create_time <= DATE_ADD(STR_TO_DATE(#{params.createTime_begin}, '%Y-%m-%d'), INTERVAL 1 DAY)


        and a.dept_code = #{params.deptCode}


        and a.check_user_post in (${params.checkUserPost})


        and a.check_owner_post in (${params.checkOwnerPost})




            and b.execute_user_id = #{params.actionPlanTrack.executeUserId}


            and b.verify_user_id = #{params.actionPlanTrack.verifyUserId}


            and b.status = #{params.actionPlanTrack.status}


            and b.finish_state = #{params.actionPlanTrack.finishState}





            and b.id is not null


            and b.id is null


    order by a.check_date desc, a.id
) a
